// GameBlock · downloaded Italy map by Neo_minigan (Sketchfab, CC BY 4.0).
// Navigation was rasterized from actual mesh triangles, not hand-drawn collision blocks.
export const ITALY_SOURCE=Object.freeze({
 creator:'Neo_minigan',title:'Cs_Italy with real light',license:'CC BY 4.0',
 url:'https://sketchfab.com/3d-models/cs-italy-with-real-light-556bd442814d4db5a9d301c4754fbb3c'
});
export const ITALY_SITES=Object.freeze([
 {id:'A',x:17,z:-16,radius:5.5,color:0xf4bb7a},
 {id:'B',x:-23,z:-21,radius:5.5,color:0x96cceb}
]);
export const ITALY_SPAWNS=Object.freeze({ct:{x:-11,z:46},t:{x:-11,z:-49}});
export const ITALY_SPAWN_POINTS=Object.freeze({
 ct:Object.freeze([[-13,45],[-11,45],[-9,45],[-12,47],[-10,47]]),
 t:Object.freeze([[-13,-50],[-11,-50],[-9,-50],[-12,-48],[-8,-48]])
});
// Each pixel is one real metre. Mask = traversable space (1), height = floor elevation.
// Half-metre navigation rebuilt from Italy's actual triangles and torso-level wall tests.
const W=141,H=249,STEP=.5,MIN_X=-35,MIN_Z=-62,COUNT=W*H;
const WALK_B64='';
const HEIGHT_B64='';
const EDGE_B64='';
function unpack(base64){
 const str=atob(base64),out=new Uint8Array(str.length);
 for(let i=0;i<str.length;i++)out[i]=str.charCodeAt(i);
 return out;
}
const packed=unpack(WALK_B64),heights=unpack(HEIGHT_B64),edges=unpack(EDGE_B64);
if(packed.length!==Math.ceil(COUNT/8)||heights.length!==COUNT||edges.length!==COUNT)
 throw new Error('Italy fine navigation data damaged');
const walk=new Uint8Array(COUNT);
for(let i=0;i<COUNT;i++)walk[i]=(packed[i>>3]>>(i&7))&1;
const cell=(x,z)=>{
 const gx=Math.round((x-MIN_X)/STEP),gz=Math.round((z-MIN_Z)/STEP);
 return gx<0||gz<0||gx>=W||gz>=H?-1:gz*W+gx;
};
const heightAtCell=id=>heights[id]/24-3;
const isOpen=(x,z)=>{const id=cell(x,z);return id>=0&&walk[id]===1};
const DIRS=[[1,0,0],[-1,0,1],[0,1,2],[0,-1,3],[1,1,4],[-1,1,5],[-1,-1,6],[1,-1,7]];
function edgeAllowed(a,b){
 if(a===b)return true;
 if(a<0||b<0||!walk[a]||!walk[b])return false;
 const dx=b%W-a%W,dz=Math.floor(b/W)-Math.floor(a/W);
 const dir=DIRS.find(([x,z])=>x===dx&&z===dz);
 return !!dir&&!!(edges[a]&(1<<dir[2]));
}
export function italyBlocks(x,z,pad=.15){
 if(!Number.isFinite(x+z))return true;
 const id=cell(x,z);
 if(id<0||!walk[id])return true;
 const p=Math.max(0,Math.min(.16,pad));
 return p>.015&&(!isOpen(x+p,z)||!isOpen(x-p,z)||!isOpen(x,z+p)||!isOpen(x,z-p));
}
export function italyGround(x,z){
 const id=cell(x,z);
 if(id>=0&&walk[id]){
  const gx=(x-MIN_X)/STEP,gz=(z-MIN_Z)/STEP;
  const ix=Math.floor(gx),iz=Math.floor(gz),u=gx-ix,v=gz-iz;
  if(ix>=0&&iz>=0&&ix+1<W&&iz+1<H){
   const a=iz*W+ix,b=a+1,c=a+W,d=c+1;
   if(walk[a]&&walk[b]&&walk[c]&&walk[d]){
    const h0=heightAtCell(a),h1=heightAtCell(b),h2=heightAtCell(c),h3=heightAtCell(d);
    if(Math.max(h0,h1,h2,h3)-Math.min(h0,h1,h2,h3)<1)
     return h0*(1-u)*(1-v)+h1*u*(1-v)+h2*(1-u)*v+h3*u*v;
   }
  }
  return heightAtCell(id);
 }
 // At the border of a stair/ledge, use the nearest existing floor instead of Y=0.
 const ix=Math.round((x-MIN_X)/STEP),iz=Math.round((z-MIN_Z)/STEP);
 for(let radius=1;radius<=12;radius++){
  let best=-1,bestDist=Infinity;
  for(let dz=-radius;dz<=radius;dz++)for(let dx=-radius;dx<=radius;dx++){
   const nx=ix+dx,nz=iz+dz;
   if(nx<0||nz<0||nx>=W||nz>=H)continue;
   const near=nz*W+nx;if(!walk[near])continue;
   const dist=dx*dx+dz*dz;
   if(dist<bestDist){best=near;bestDist=dist}
  }
  if(best>=0)return heightAtCell(best);
 }
 return 0;
}
export function italyCanTraverse(start,goal,pad=.13){
 const distance=Math.hypot(goal.x-start.x,goal.z-start.z);
 let prev=cell(start.x,start.z);
 if(prev<0||!walk[prev]||!Number.isFinite(distance))return false;
 // Direct adjoining cells may share an exact diagonal corner; use the measured
 // diagonal edge instead of roundoff-dependent intermediate raster samples.
 if(distance<=.73){
  const adjacent=cell(goal.x,goal.z);
  if(edgeAllowed(prev,adjacent))return !italyBlocks(goal.x,goal.z,pad);
 }
 const samples=Math.max(1,Math.ceil(distance/.14));
 for(let i=1;i<=samples;i++){
  const t=i/samples,x=start.x+(goal.x-start.x)*t,z=start.z+(goal.z-start.z)*t;
  const next=cell(x,z);
  if(next<0||!walk[next]||!edgeAllowed(prev,next))return false;
  prev=next;
 }
 return !italyBlocks(goal.x,goal.z,pad);
}
// Reachability prevents the squad planner from targeting isolated upper roof polygons.
const connected=new Uint8Array(COUNT);
{
 const seed=cell(-11,46),queue=new Int32Array(COUNT);
 let head=0,tail=0;
 if(seed>=0&&walk[seed]){queue[tail++]=seed;connected[seed]=1}
 while(head<tail){
  const p=queue[head++],x=p%W,z=Math.floor(p/W);
  for(const [dx,dz,bit] of DIRS){
   if(!(edges[p]&(1<<bit)))continue;
   const nx=x+dx,nz=z+dz;
   if(nx<0||nz<0||nx>=W||nz>=H)continue;
   const q=nz*W+nx;if(connected[q])continue;
   connected[q]=1;queue[tail++]=q;
  }
 }
}
export const italyReachable=(x,z)=>{const id=cell(x,z);return id>=0&&!!connected[id]};
function nearCell(x,z){
 const original=cell(x,z);
 if(original>=0&&walk[original])return original;
 const gx=Math.round((x-MIN_X)/STEP),gz=Math.round((z-MIN_Z)/STEP);
 for(let radius=1;radius<=24;radius++){
  let best=-1,dist=Infinity;
  for(let dz=-radius;dz<=radius;dz++)for(let dx=-radius;dx<=radius;dx++){
   const xx=gx+dx,zz=gz+dz;
   if(xx<0||zz<0||xx>=W||zz>=H)continue;
   const id=zz*W+xx;if(!walk[id])continue;
   const d=dx*dx+dz*dz;
   if(d<dist){best=id;dist=d}
  }
  if(best>=0)return best;
 }
 return -1;
}
export function findItalyPath(start,goal){
 if(!Number.isFinite(start.x+start.z+goal.x+goal.z))return [];
 if(italyCanTraverse(start,goal,.10))return [goal];
 const src=nearCell(start.x,start.z),dst=nearCell(goal.x,goal.z);
 if(src<0||dst<0)return [];
 const previous=new Int32Array(COUNT);previous.fill(-1);
 const queue=new Int32Array(COUNT);
 let head=0,tail=0;queue[tail++]=src;previous[src]=src;
 while(head<tail&&previous[dst]<0){
  const p=queue[head++],x=p%W,z=Math.floor(p/W);
  for(const [dx,dz,bit] of DIRS){
   if(!(edges[p]&(1<<bit)))continue;
   const nx=x+dx,nz=z+dz;
   if(nx<0||nz<0||nx>=W||nz>=H)continue;
   const next=nz*W+nx;
   if(previous[next]>=0)continue;
   previous[next]=p;queue[tail++]=next;
  }
 }
 if(previous[dst]<0)return [];
 const path=[];let p=dst;
 while(p!==src){
  path.push({x:MIN_X+p%W*STEP,z:MIN_Z+Math.floor(p/W)*STEP});
  p=previous[p];
 }
 path.reverse();
 const points=[start,...path,goal],result=[];
 let current=0;
 while(current<points.length-1&&result.length<320){
  let next=current+1,limit=Math.min(points.length-1,current+36);
  for(let i=limit;i>current+1;i--){
   if(italyCanTraverse(points[current],points[i],.10)){next=i;break}
  }
  result.push(points[next]);current=next;
 }
 return result;
}
export const ITALY_NAV_STATS=Object.freeze({width:W,height:H,step:STEP,freeCells:15437,reachableCells:10403,modelBytes:11115840});

// GLB has embedded textures and source-space node rotations.
// Transform aligns streets and the loaded navigation surface at ground Y≈0.
export function buildItalyMap(THREE,root){
 return new Promise((resolve,reject)=>{
  if(!THREE.GLTFLoader){reject(new Error('GLTFLoader not ready'));return;}
  new THREE.GLTFLoader().load('cs_italy_with_real_light.glb',gltf=>{
   const world=gltf.scene;
   world.position.set(5.726545556,-28.55876471,-33.258728794);
   root.add(world);world.updateMatrixWorld(true);
   const meshes=[];
   world.traverse(node=>{
    if(!node.isMesh)return;
    node.name='Italy GLB: '+node.name;node.receiveShadow=true;
    const materials=Array.isArray(node.material)?node.material:[node.material];
    for(const material of materials)if(material){
     material.side=THREE.DoubleSide;
     material.toneMapped=false; // Imported Italy has baked light in unlit atlases.
     if(material.map){
      material.map.encoding=THREE.sRGBEncoding;
      const previous=material.onBeforeCompile;
      material.onBeforeCompile=shader=>{
       previous?.(shader);
       shader.fragmentShader=shader.fragmentShader.replace('#include <map_fragment>',
        '#include <map_fragment>\n diffuseColor.rgb = mix(diffuseColor.rgb, sqrt(max(diffuseColor.rgb, vec3(0.0))), 0.52);');
      };
      material.customProgramCacheKey=()=> 'italy-bright-baked-v2';
      material.needsUpdate=true;
     }
    }
    meshes.push(node);
   });
   if(meshes.length<10){root.remove(world);reject(new Error('Italy geometry is incomplete'));return;}
   resolve({floor:meshes[0],obstacles:meshes.slice(1),world,meshCount:meshes.length});
  },undefined,error=>reject(error||new Error('Failed to load Italy map GLB')));
 });
}
